      "type": "n8n-nodes-base.code",
      "typeVersion": 2,
      "position": [460, 300]
    }
  ],
  "connections": {
    "User Telemetry Webhook": {
      "main": [[{ "node": "Evaluate PQL Activation", "type": "main", "index": 0 }]]
    }
  }
}
```

